<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Application\Service;

use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetReadGateway;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAsset;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetReadGateway;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAsset;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetReadGateway;

/**
 * Computes public URL paths for asset directories and keeps the local
 * filesystem mirror in sync (write/delete) for individual asset files.
 *
 * Path conventions (relative to .assets/):
 *   themes/{themeUid}/{code}
 *   templates/{templateUid}/{code}            (global asset)
 *   templates/{templateUid}/{tenantUid}/{code} (tenant-scoped asset)
 *   snippets/{snippetUid}/{code}
 */
class DocumentAssetDumpService
{
    private readonly string $assetsBase;
    private readonly string $localRoot;

    public function __construct(
        AppConfig $config,
        Context $context,
        private readonly ThemeAssetReadGateway $themeAssetGateway,
        private readonly TemplateAssetReadGateway $templateAssetGateway,
        private readonly SnippetAssetReadGateway $snippetAssetGateway,
    ) {
        $this->assetsBase = $config->get('oidc.theme.path', $context->getBaseUrl() . '/');
        $realPath         = realpath('.');
        $this->localRoot  = ($realPath !== false ? $realPath : '.') . '/.assets';
    }

    // -------------------------------------------------------------------------
    // Public URL path helpers (no I/O)
    // -------------------------------------------------------------------------

    public function themeAssetsPath(string $themeUid): string
    {
        return "{$this->assetsBase}.assets/themes/{$themeUid}";
    }

    public function templateAssetsPath(string $templateUid, ?string $tenantUid = null): string
    {
        $sub = $tenantUid !== null ? "{$templateUid}/{$tenantUid}" : $templateUid;
        return "{$this->assetsBase}.assets/templates/{$sub}";
    }

    public function snippetAssetsPath(string $snippetUid): string
    {
        return "{$this->assetsBase}.assets/snippets/{$snippetUid}";
    }

    // -------------------------------------------------------------------------
    // File sync: theme assets
    // -------------------------------------------------------------------------

    public function dumpThemeAsset(ThemeAsset $asset): void
    {
        if (!$asset->isEnabled()) {
            $this->removeThemeAsset($asset);
            return;
        }
        $dir = $this->localRoot . '/themes/' . ($asset->getTheme()->uid() ?? '');
        $this->writeAsset(
            $dir,
            $asset->getCode(),
            fn () => $this->themeAssetGateway->readContent($asset->getContent()),
        );
    }

    public function removeThemeAsset(ThemeAsset $asset): void
    {
        $dir = $this->localRoot . '/themes/' . ($asset->getTheme()->uid() ?? '');
        $this->deleteAsset($dir, $asset->getCode());
    }

    // -------------------------------------------------------------------------
    // File sync: template assets
    // -------------------------------------------------------------------------

    public function dumpTemplateAsset(TemplateAsset $asset): void
    {
        if (!$asset->isEnabled()) {
            $this->removeTemplateAsset($asset);
            return;
        }
        $dir = $this->localRoot . '/templates/' . $this->templateSubDir($asset);
        $this->writeAsset(
            $dir,
            $asset->getCode(),
            fn () => $this->templateAssetGateway->readContent($asset->getContent()),
        );
    }

    public function removeTemplateAsset(TemplateAsset $asset): void
    {
        $dir = $this->localRoot . '/templates/' . $this->templateSubDir($asset);
        $this->deleteAsset($dir, $asset->getCode());
    }

    // -------------------------------------------------------------------------
    // File sync: snippet assets
    // -------------------------------------------------------------------------

    public function dumpSnippetAsset(SnippetAsset $asset): void
    {
        if (!$asset->isEnabled()) {
            $this->removeSnippetAsset($asset);
            return;
        }
        $dir = $this->localRoot . '/snippets/' . ($asset->getSnippet()->uid() ?? '');
        $this->writeAsset(
            $dir,
            $asset->getCode(),
            fn () => $this->snippetAssetGateway->readContent($asset->getContent()),
        );
    }

    public function removeSnippetAsset(SnippetAsset $asset): void
    {
        $dir = $this->localRoot . '/snippets/' . ($asset->getSnippet()->uid() ?? '');
        $this->deleteAsset($dir, $asset->getCode());
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    private function templateSubDir(TemplateAsset $asset): string
    {
        $templateUid = $asset->getTemplate()->uid() ?? '';
        $tenantUid   = $asset->getTenant()?->uid();
        return $tenantUid !== null ? "{$templateUid}/{$tenantUid}" : $templateUid;
    }

    private function writeAsset(string $dir, string $code, callable $reader): void
    {
        if ($code === '' || str_contains($code, '/') || str_contains($code, '..')) {
            return;
        }
        if (!is_dir($dir)) {
            mkdir($dir, 0777, true);
        }
        $binary = $reader();
        if (!$binary->isStreamOpen()) {
            return;
        }
        $fp = fopen($dir . '/' . $code, 'wb');
        if ($fp !== false) {
            stream_copy_to_stream($binary->stream, $fp);
            fclose($fp);
        }
    }

    private function deleteAsset(string $dir, string $code): void
    {
        if ($code === '' || str_contains($code, '/') || str_contains($code, '..')) {
            return;
        }
        $path = $dir . '/' . $code;
        if (is_file($path)) {
            unlink($path);
        }
    }
}
